import{_ as e,c as o,o as t,ag as r}from"./chunks/framework.ymCRTBvy.js";const h=JSON.parse('{"title":"1.1_创建不含Storyboard的新项目","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_mvvm/1.1_创建不含Storyboard的新项目.md","filePath":"swift/uikit/uikit_mvvm/1.1_创建不含Storyboard的新项目.md"}'),i={name:"swift/uikit/uikit_mvvm/1.1_创建不含Storyboard的新项目.md"};function n(d,a,s,l,c,_){return t(),o("div",null,a[0]||(a[0]=[r('<h1 id="_1-1-创建不含storyboard的新项目" tabindex="-1">1.1_创建不含Storyboard的新项目 <a class="header-anchor" href="#_1-1-创建不含storyboard的新项目" aria-label="Permalink to &quot;1.1_创建不含Storyboard的新项目&quot;">​</a></h1><h2 id="启动xcode并选择模板" tabindex="-1">启动Xcode并选择模板 <a class="header-anchor" href="#启动xcode并选择模板" aria-label="Permalink to &quot;启动Xcode并选择模板&quot;">​</a></h2><p>恭喜你踏上iOS 18纯代码编程之旅！🚀 首先，你需要启动Xcode。在欢迎界面，你会看到“Create a new Xcode project”的选项，点击它，这将是你的起点。选择正确的项目模板至关重要，因为它为你的应用奠定了基础。</p><h2 id="选择app模板" tabindex="-1">选择App模板 <a class="header-anchor" href="#选择app模板" aria-label="Permalink to &quot;选择App模板&quot;">​</a></h2><p>在接下来的模板选择界面，你会看到多种应用类型。对于纯代码项目，请务必选择“iOS”选项卡下的“App”模板。这个模板提供了一个最基础的结构，非常适合我们从零开始构建UI。避免选择任何包含“Game”或“Document App”字样的模板，因为它们会引入不必要的复杂性。</p><h2 id="配置项目选项" tabindex="-1">配置项目选项 <a class="header-anchor" href="#配置项目选项" aria-label="Permalink to &quot;配置项目选项&quot;">​</a></h2><p>现在，你需要为你的新项目填写一些关键信息。这些配置将定义你的应用身份和基本设置。</p><ul><li><strong>Product Name (产品名称)</strong>: 输入你的应用名称，例如“PureCodeMVVM”。这个名称将显示在用户的设备主屏幕上。</li><li><strong>Organization Identifier (组织标识符)</strong>: 通常是你的公司或个人域名的反向形式，例如“com.yourcompany”。这确保了你的应用在全球范围内的唯一性。</li><li><strong>Interface (界面)</strong>: <strong>这是最关键的一步！</strong> 请务必从下拉菜单中选择“Storyboard”旁边的“SwiftUI”或“None”。为了纯代码开发，我们选择“None”来完全避免Storyboard。这是一个重要的决定，因为它将引导你走向更灵活的UI构建方式。</li><li><strong>Language (语言)</strong>: 选择“Swift”。Swift是Apple推荐的现代编程语言，拥有出色的性能和安全性。</li><li><strong>Use Core Data (使用Core Data)</strong>: 确保这个选项<strong>未被勾选</strong>。我们将在后续章节中探讨数据持久化，但现在不需要它。</li><li><strong>Include Tests (包含测试)</strong>: 勾选这个选项是一个好习惯。单元测试和UI测试对于确保代码质量至关重要。</li></ul><h2 id="保存项目" tabindex="-1">保存项目 <a class="header-anchor" href="#保存项目" aria-label="Permalink to &quot;保存项目&quot;">​</a></h2><p>填写完所有信息后，点击“Next”按钮。Xcode会提示你选择一个位置来保存你的项目。选择一个你容易找到的文件夹，然后点击“Create”。恭喜你！🎉 你已经成功创建了一个不含Storyboard的全新iOS项目。</p><h2 id="探索项目结构" tabindex="-1">探索项目结构 <a class="header-anchor" href="#探索项目结构" aria-label="Permalink to &quot;探索项目结构&quot;">​</a></h2><p>项目创建后，你会看到Xcode的项目导航器。你会发现项目结构非常简洁，没有<code>Main.storyboard</code>文件。这正是我们想要的！你将主要与<code>AppDelegate.swift</code>和<code>SceneDelegate.swift</code>文件打交道，它们是应用生命周期和UI场景管理的核心。在iOS 18中，<code>SceneDelegate</code>扮演着至关重要的角色，它负责管理应用的各个UI场景，例如多窗口支持。</p><h2 id="准备下一步" tabindex="-1">准备下一步 <a class="header-anchor" href="#准备下一步" aria-label="Permalink to &quot;准备下一步&quot;">​</a></h2><p>现在，你的项目已经准备就绪，可以开始纯代码UI开发了。你已经迈出了掌握iOS 18 UIKit纯代码编程的第一步，这绝对是一个令人兴奋的开始！💪 接下来，我们将深入探讨如何配置和管理你的应用场景。</p>',14)]))}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
